CREATE OR REFRESH MATERIALIZED VIEW `erp_prod`.`silver`.`customer_balances` (
  CONSTRAINT `customer_id_not_null` EXPECT (`customer_id` IS NOT NULL)
)
COMMENT 'Open balance per customer.'
CLUSTER BY AUTO
AS
SELECT c.customer_id, c.name, SUM(i.amount) AS balance
FROM `erp_prod`.`bronze`.`customers` AS c
JOIN `erp_prod`.`bronze`.`invoices` AS i ON i.customer_id = c.customer_id
WHERE i.__END_AT IS NULL AND i.status = 'open'
GROUP BY c.customer_id, c.name;
